// fake-snippets-api/lib/middleware/with-error-handling.ts
import kleur from "kleur";
var withErrorHandling = async (req, ctx, next) => {
  try {
    return await next(req, ctx);
  } catch (error) {
    console.error(kleur.red("Intercepted error:"), error);
    if (error instanceof Response) {
      return error;
    }
    return ctx.json(
      {
        ok: false,
        error: {
          message: error?.message,
          error_code: error?.error_code ?? "internal_server_error"
        }
      },
      { status: error?.status || 500 }
    );
  }
};

// fake-snippets-api/lib/middleware/with-request-logging.ts
import kleur2 from "kleur";
kleur2.enabled = true;
var colorStatus = (status) => {
  if (status >= 500) {
    return kleur2.red(status.toString());
  }
  if (status >= 400) {
    return kleur2.yellow(status.toString());
  }
  return kleur2.green(status.toString());
};
var withRequestLogging = async (req, ctx, next) => {
  if (!ctx.logger) {
    ctx.logger = {
      error: (...args) => console.error(...args),
      info: (...args) => console.log(...args),
      warn: (...args) => console.warn(...args),
      debug: (...args) => console.log(...args)
    };
  }
  try {
    ctx.logger.info(kleur2.blue(`> ${req.method} ${req.url}`));
    const response = await next(req, ctx);
    try {
      const responseBody = await response.clone().text();
      ctx.logger.info(
        `< ${colorStatus(response.status)} ${kleur2.gray(responseBody.slice(0, 40).replace(/(\r\n|\n|\r)/gm, ""))}`
      );
    } catch (e) {
      ctx.logger.info(`< ${colorStatus(response.status)}`);
    }
    return response;
  } catch (e) {
    ctx.logger.info(kleur2.red(`< ERROR ${e.toString().slice(0, 50)}...`));
    throw e;
  }
};

