// fake-snippets-api/routes/api/aistream/[...anyroute].ts
import { ReadableStream } from "stream/web";
var anyroute_default2 = async (req) => {
  const url = new URL(req.url);
  const anthropicApiKey = process.env.ANTHROPIC_API_KEY;
  if (!anthropicApiKey) {
    return new Response("Anthropic API key is not set", { status: 500 });
  }
  const anthropicUrl = "https://api.anthropic.com" + url.pathname.replace(/^\/api\/ai/, "");
  const headers = new Headers(req.headers);
  headers.set("x-api-key", `${anthropicApiKey}`);
  headers.set("Accept", "text/event-stream");
  headers.set("Cache-Control", "no-cache");
  headers.set("Connection", "keep-alive");
  console.log("sending request to anthropic");
  const response = await fetch(anthropicUrl, {
    method: req.method,
    headers,
    body: req.body,
    // @ts-ignore
    duplex: "half"
  });
  if (!response.ok) {
    return new Response(
      `Anthropic API returned an error: ${response.status} ${response.statusText}`,
      {
        status: response.status
      }
    );
  }
  const stream = new ReadableStream({
    async start(controller) {
      const reader = response.body.getReader();
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done)
            break;
          controller.enqueue(value);
        }
      } finally {
        reader.releaseLock();
        controller.close();
      }
    }
  });
  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive"
    }
  });
};

