// fake-snippets-api/routes/api/bug_reports/upload_file.ts
import { Buffer as Buffer2 } from "node:buffer";

// fake-snippets-api/utils/normalizeProjectFilePath.ts
var RESTRICTED_DIRS = ["/node_modules/", "/dist/", "/.git/"];
var normalizeProjectFilePathAndValidate = (rawPath) => {
  const normalizedPath = normalizeProjectFilePath(rawPath);
  if (normalizedPath.includes("../")) {
    throw new Error(
      "Invalid project file path. Parent directories are not allowed."
    );
  }
  if (RESTRICTED_DIRS.some((dir) => normalizedPath.includes(dir))) {
    throw new Error(
      `Invalid project file path. Restricted directories (${RESTRICTED_DIRS.map(
        (rd) => rd.slice(1, -1)
      ).join(", ")}) are not allowed.`
    );
  }
  return normalizedPath;
};
var normalizeProjectFilePath = (rawPath) => {
  let normalizedPath = rawPath.trim();
  normalizedPath = normalizedPath.replace(/\/+/g, "/");
  normalizedPath = normalizedPath.replace(/^\.\//, "");
  normalizedPath = normalizedPath.replace(/\/$/, "");
  normalizedPath = normalizedPath.replace(/\\/g, "/");
  normalizedPath = normalizedPath.replace(/^\//, "");
  return normalizedPath;
};

