// fake-snippets-api/routes/api/orders/get.ts
import { z as z31 } from "zod";
var get_default4 = withRouteSpec({
  methods: ["GET", "POST"],
  auth: "none",
  commonParams: z31.object({
    order_id: z31.string().optional(),
    stripe_checkout_session_id: z31.string().optional(),
    session_id: z31.string().optional()
  }).refine(
    ({ order_id, stripe_checkout_session_id, session_id }) => Boolean(order_id || stripe_checkout_session_id || session_id),
    "order_id or stripe_checkout_session_id is required"
  ),
  jsonResponse: z31.object({
    ok: z31.boolean(),
    order: publicOrderSchema
  })
})(async (req, ctx) => {
  const stripeCheckoutSessionId = req.commonParams.stripe_checkout_session_id ?? req.commonParams.session_id;
  const order = ctx.db.orders.find((candidate) => {
    if (req.commonParams.order_id) {
      return candidate.order_id === req.commonParams.order_id;
    }
    return candidate.stripe_checkout_session_id === stripeCheckoutSessionId;
  });
  if (!order) {
    return ctx.error(404, {
      error_code: "order_not_found",
      message: "Order not found"
    });
  }
  let latestOrder = order;
  if (order.stripe_checkout_session_id && !order.is_stripe_checkout_session_expired) {
    try {
      const checkoutSession = await retrieveFakeStripeCheckoutSession({
        requestUrl: req.url,
        stripeCheckoutSessionId: order.stripe_checkout_session_id
      });
      const updates = getStripeCheckoutFlags(checkoutSession);
      ctx.db.updateOrder(order.order_id, {
        ...updates,
        stripe_checkout_session_url: updates.is_stripe_checkout_session_expired ? null : order.stripe_checkout_session_url
      });
      latestOrder = ctx.db.getOrderById(order.order_id) ?? order;
    } catch (error) {
      console.warn("Failed to refresh fake Stripe checkout session state", {
        error,
        order_id: order.order_id
      });
    }
  }
  return ctx.json({
    ok: true,
    order: publicMapOrder(latestOrder)
  });
});

