        // Add star timestamp
        star_count: ctx.db.getStarCount(pkg.package_id),
        is_starred: ctx.auth ? ctx.db.hasStarred(ctx.auth.account_id, pkg.package_id) : false,
        version: pkg.latest_version || "0.0.1",
